text:
{
  "questions": [
    {
      "n": 1,
      "start": "Wie beurteilt die Regierung die aktuelle wirtschaftliche Lage",
      "end": "des Kantons Schaffhausen im Vergleich zu anderen Kantonen der Nordostschweiz, insbesondere im Hinblick auf die Arbeitslosigkeit?"
    },
    {
      "n": 2,
      "start": "Welche konkrete Massnahme hat die Wirtschaftsförderung",
      "end": "in den letzten fünf Jahren ergriffen, um Arbeitsplätze zu erhalten und neue zu schaffen?"
    },
    {
      "n": 3,
      "start": "Wie viele Unternehmen konnten durch die Wirtschaftsförderung",
      "end": "tatsächlich in den Kanton Schaffhausen geholt werden, und wie viele Arbeitsplätze wurden dadurch geschaffen?"
    },
    {
      "n": 4,
      "start": "Wie hoch ist der tatsächliche finanzielle Aufwand für die Wirtschaftsförderung",
      "end": "und die Geschäftsstelle Regional- und Standortentwicklung, und wie wird der Erfolg dieser Institutionen gemessen?"
    },
    {
      "n": 5,
      "start": "Warum wird die starke Rolle des Finanzdepartements bei der Ansiedlung",
      "end": "von Unternehmen kaum thematisiert, obwohl steuerliche Rahmenbedingungen ein ausschlaggebender Standortfaktor sind?"
    },
    {
      "n": 6,
      "start": "Wie gedenkt die Regierung sicherzustellen, dass auch KMU, Industrie",
      "end": "und Dienstleistungsbetriebe in die Wirtschaftsförderung integriert werden, um eine ausgewogene Branchendiversifikation zu erreichen?"
    },
    {
      "n": 7,
      "start": "Ist die Regierung der Meinung, dass der Vergleich von Innovationszentren",
      "end": "mit Trainingszentren aus dem Spitzensport ein adäquates Modell für die Wirtschaftsförderung eines ganzen Kantons ist? Falls ja, warum?"
    },
    {
      "n": 8,
      "start": "Gibt es Überlegungen, die Strategie der Wirtschaftsförderung anzupassen,",
      "end": "um gezielter auf die Reduktion der Arbeitslosigkeit und die Förderung von Unternehmen mit nachhaltigem Wachstumspotenzial hinzuwirken?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Geopolitische Unsicherheiten und eine zunehmende Instabilität belasten die Weltwirtschaft und treffen insbesondere die exportorientierten Unternehmen im Kanton Schaffhausen.",
      "end": "Im Jahr 2024 meldeten 22 Unternehmen Kurzarbeit an, gegenüber 15 im Vorjahr. Die Prognosen für den Arbeitsmarkt bleiben getrübt: Die Arbeitslosigkeit ist moderat gestiegen und die kurzfristigen Beschäftigungsaussichten haben sich verschlechtert."
    },
    {
      "n": 2,
      "start": "Im Auftrag des Regierungsrats setzt sich die Wirtschaftsförderung des Kantons Schaffhausen gemäss ihrem gesetzlichen und vertraglichen Auftrag mit verschiedenen Massnahmen dafür ein, Arbeitsplätze zu erhalten und neue zu schaffen.",
      "end": "Dazu gehören insbesondere: Standortmarketing und Ansiedlung neuer Unternehmen; Bestandspflege; Jungunternehmerförderung; Technologie- und Innovationsförderung; Wohnortmarketing und Arbeitskräftegewinnung; Regional- und Standortentwicklung (RSE)."
    },
    {
      "n": 3,
      "start": "Im Jahr 2024 wurden 19 Ansiedlungen verzeichnet, verglichen mit 21 im Jahr 2023.",
      "end": "Die Anzahl der durch Ansiedlungstätigkeiten sowie durch einzelbetriebliche Fördermassnahmen geschaffenen Arbeitsplätze wird jeweils im Verwaltungsbericht ausgewiesen."
    },
    {
      "n": 4,
      "start": "Die finanziellen Aufwendungen für die Wirtschaftsförderung und die Geschäftsstelle RSE sind in den Verwaltungsberichten ausgewiesen.",
      "end": "Die Wirkungsmessung stützt sich dabei einerseits auf quantitative Kennzahlen wie die Anzahl Unternehmensansiedlungen, geschaffene Arbeitsplätze oder generierte Steuereinnahmen, welche direkte Rückschlüsse auf die Wirksamkeit einzelner Massnahmen zulassen."
    },
    {
      "n": 5,
      "start": "Es gehört zu den Stärken des Kantons Schaffhausen, dass sich Unternehmen bei allen Fragen an eine für sie gut erkennbare Stelle wenden können («One-Stop-Shop»).",
      "end": "Die Wirtschaftsförderung hat gemäss ihrem gesetzlichen Auftrag diese Funktion als zentrale Anlauf-, Koordinations- und Auskunftsstelle für Unternehmen und damit durchaus gewollt eine höhere Sichtbarkeit als andere (Verwaltungs-) Stellen."
    },
    {
      "n": 6,
      "start": "Die Sicherstellung einer ausgewogenen Branchendiversifikation ist ein zentrales Ziel des Wirtschaftsförderungsgesetzes – und damit ein von den Schaffhauser Stimmbürgerinnen und Stimmbürgern demokratisch legitimiertes Anliegen.",
      "end": "Der Regierungsrat ist gesetzlich verpflichtet, diesen Auftrag umzusetzen, und beauftragt damit die Wirtschaftsförderung."
    },
    {
      "n": 7,
      "start": "Ist die Regierung der Meinung, dass der Vergleich von Innovationszentren mit Trainingszentren aus dem Spitzensport ein adäquates Modell für die Wirtschaftsförderung eines ganzen Kantons ist?",
      "end": "Falls ja, warum?"
    },
    {
      "n": 8,
      "start": "Gibt es Überlegungen, die Strategie der Wirtschaftsförderung anzupassen, um gezielter auf die Reduktion der Arbeitslosigkeit und die Förderung von Unternehmen mit nachhaltigem Wachstumspotenzial hinzuwirken?",
      "end": "null"
    }
  ],
  "submitter": "Walter Hotz",
  "co_signatories": [],
  "recommendation": "accept",
  "reasoning": {
    "start": "Seit der Einführung des Wirtschaftsförderungsgesetzes im Jahr 1999 führt der Kanton Schaffhausen eine Wirtschaftsförderungsstelle als Anlauf, Informations- und Koordinationsorgan zwischen Wirtschaft, Politik und Verwaltung.",
    "end": "Der Regierungsrat beantwortet die Fragen umfassend, transparent und mit Bezug auf gesetzliche Grundlagen, Kennzahlen und Verwaltungsberichte."
  }
}
